#!/usr/bin/env bash
# Export pinned Python requirements for production and dev/CI environments.
#
# Generated from uv.lock (do not edit by hand):
#   requirements.txt      — distributed/runtime (FOSSA release gate)
#   dev-requirements.txt  — dev + test groups (not shipped; LGPL allowed per legal/POLICY.md)
#   fossa-deps.yml        — FOSSA referenced-dependencies (Python + Rust SDK bindings)
#
# Usage:
#   ./scripts/deps/export-requirements.sh
#   ./scripts/deps/export-requirements.sh --check

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "${SCRIPT_DIR}/../.." && pwd)"

PROD_FILE="${REPO_ROOT}/requirements.txt"
DEV_FILE="${REPO_ROOT}/dev-requirements.txt"
DO_CHECK=0

while [[ $# -gt 0 ]]; do
	case "$1" in
	--check)
		DO_CHECK=1
		shift
		;;
	-h | --help)
		cat <<'EOF'
Usage: export-requirements.sh [--check]

Writes requirements.txt (production) and dev-requirements.txt (dev/CI) at repo root.
With --check, fails if committed files differ from a fresh uv export.
EOF
		exit 0
		;;
	*)
		echo "error: unknown arg: $1 (try --help)" >&2
		exit 1
		;;
	esac
done

run_uv() {
	if command -v uv >/dev/null 2>&1; then
		uv "$@"
	elif command -v rtk >/dev/null 2>&1; then
		rtk uv "$@"
	else
		echo "error: missing required command: uv" >&2
		exit 1
	fi
}

require_cmd() {
	command -v uv >/dev/null 2>&1 || {
		echo "error: missing required command: uv" >&2
		exit 1
	}
}

export_requirements() {
	local prod_out="$1"
	local dev_out="$2"
	local prod_tmp dev_tmp

	require_cmd
	[[ -f "${REPO_ROOT}/pyproject.toml" ]] || {
		echo "error: missing pyproject.toml at ${REPO_ROOT}" >&2
		exit 1
	}
	[[ -f "${REPO_ROOT}/uv.lock" ]] || {
		echo "error: missing uv.lock (run: uv lock)" >&2
		exit 1
	}

	prod_tmp="$(mktemp "${TMPDIR:-/tmp}/export-requirements-prod.XXXXXX")"
	dev_tmp="$(mktemp "${TMPDIR:-/tmp}/export-requirements-dev.XXXXXX")"

	(
		cd "${REPO_ROOT}"
		run_uv export --quiet --frozen --all-extras --no-default-groups --no-dev \
			--no-group dev --no-group test --no-header \
			--format requirements.txt --output-file "${prod_tmp}"
		run_uv export --quiet --frozen --all-extras --group dev --group test \
			--no-header --format requirements.txt --output-file "${dev_tmp}"
	)

	sanitize_requirements_body "${prod_tmp}"
	sanitize_requirements_body "${dev_tmp}"

	write_requirements_file "${prod_out}" "production (FOSSA release gate)" "${prod_tmp}"
	write_requirements_file "${dev_out}" "dev/CI (not shipped)" "${dev_tmp}"
	write_fossa_deps "${prod_out}" "$(dirname "${prod_out}")/fossa-deps.yml"
	rm -f "${prod_tmp}" "${dev_tmp}"
}

# Drop uv's default header (embeds machine-specific --output-file paths) and normalize
# editable installs to repo-relative paths so exports are stable across machines.
sanitize_requirements_body() {
	local file="$1"

	awk -v repo_root="${REPO_ROOT}" '
		BEGIN { skipping_uv_header = 0 }
		/^# This file was autogenerated by uv via the following command:/ {
			skipping_uv_header = 1
			next
		}
		skipping_uv_header == 1 {
			skipping_uv_header = 0
			next
		}
		/^-e / {
			path = substr($0, 4)
			gsub(/[[:space:]]+\\$/, "", path)
			if (path == "." || path == repo_root || path == repo_root "/.") {
				print "-e ."
				next
			}
			if (path == "./sdk/python" || path == repo_root "/sdk/python") {
				print "-e ./sdk/python"
				next
			}
		}
		{ print }
	' "${file}" >"${file}.sanitized"
	mv "${file}.sanitized" "${file}"
}

write_requirements_file() {
	local out="$1"
	local scope="$2"
	local body="$3"

	{
		printf '%s\n' \
			"# Autogenerated by scripts/deps/export-requirements.sh — do not edit by hand." \
			"# Scope: ${scope}. Regenerate: ./scripts/deps/export-requirements.sh"
		cat "${body}"
	} >"${out}"
}

# dev-requirements.txt is not named requirements*.txt so FOSSA setuptools@./ static scans skip it.
write_fossa_deps() {
	local req_file="$1"
	local out_file="$2"
	local cargo_entries

	cargo_entries="$("${SCRIPT_DIR}/export-fossa-cargo-sdk.sh")"

	{
		printf '%s\n' \
			"# Autogenerated by scripts/deps/export-requirements.sh — do not edit by hand." \
			"# Production deps for FOSSA. Regenerate:" \
			"#   ./scripts/deps/export-requirements.sh (Python + Rust SDK entries)" \
			"#   ./scripts/local/dev/cargo-build-sdk-release.sh (Rust SDK build + regenerate)" \
			"referenced-dependencies:"
		awk '
			/^#/ { next }
			/^[[:space:]]*$/ { next }
			/^-e / { next }
			{
				line = $0
				gsub(/ \\$/, "", line)
				if (index(line, "==") == 0) next
				split(line, parts, "==")
				name = parts[1]
				version = parts[2]
				sub(/[[:space:]].*/, "", version)
				sub(/\[.*\]$/, "", name)
				if (name == "" || version == "") next
				printf("  - type: pypi\n    name: %s\n    version: \"%s\"\n", name, version)
			}
		' "${req_file}"
		if [[ -n "${cargo_entries}" ]]; then
			printf '%s\n' "${cargo_entries}"
		fi
	} >"${out_file}"
}

if [[ "${DO_CHECK}" -eq 1 ]]; then
	tmp_dir="$(mktemp -d "${TMPDIR:-/tmp}/export-requirements.XXXXXX")"
	trap 'rm -rf "${tmp_dir}"' EXIT
	export_requirements "${tmp_dir}/requirements.txt" "${tmp_dir}/dev-requirements.txt"

	status=0
	for name in requirements.txt dev-requirements.txt fossa-deps.yml; do
		if [[ ! -f "${REPO_ROOT}/${name}" ]]; then
			echo "error: missing ${name} (run: ./scripts/deps/export-requirements.sh)" >&2
			status=1
			continue
		fi
		case "${name}" in
		fossa-deps.yml)
			if ! diff -q "${REPO_ROOT}/${name}" "${tmp_dir}/${name}" >/dev/null; then
				echo "error: ${name} is out of sync (run: ./scripts/deps/export-requirements.sh or ./scripts/local/dev/cargo-build-sdk-release.sh)" >&2
				status=1
			fi
			;;
		*)
			if ! diff -q "${REPO_ROOT}/${name}" "${tmp_dir}/${name}" >/dev/null; then
				echo "error: ${name} is out of sync with uv.lock (run: ./scripts/deps/export-requirements.sh)" >&2
				status=1
			fi
			;;
		esac
	done
	exit "${status}"
fi

export_requirements "${PROD_FILE}" "${DEV_FILE}"
